/* Runtime loader for mpegts.js. */
window.__mpegtsReady = new Promise(function(resolve, reject) {
  if (window.mpegts) return resolve(window.mpegts);
  var s = document.createElement('script');
  s.src = 'https://cdn.jsdelivr.net/npm/mpegts.js@1.8.0/dist/mpegts.min.js';
  s.onload = function(){ resolve(window.mpegts); };
  s.onerror = reject;
  document.head.appendChild(s);
});
